# Auto-generated compact Awesome-AITools catalog data
# 100% Pure Python Standard Library (pip = 0)
import base64
import json
import zlib

_RAW_B64 = ""

def load_catalog_data():
    decompressed = zlib.decompress(base64.b64decode(_RAW_B64))
    data = json.loads(decompressed.decode("utf-8"))
    for item in data.get("t", []):
        if len(item) > 3 and isinstance(item[3], str) and item[3].startswith("gh:"):
            item[3] = "https://github.com/" + item[3][3:]
    return data
